mapper.select:
SELECT * FROM 0721acgn.tb_cartoons


        AND (
            `genre` = #{genre}
            OR LOCATE(#{genre}, IFNULL(`genre`, '')) > 0
        )


        AND status = #{status}


        AND LENGTH(TRIM(IFNULL(releasedate,''))) >= 4
        AND CAST(LEFT(TRIM(releasedate), 4) AS UNSIGNED) >= #{yearMin}


        AND LENGTH(TRIM(IFNULL(releasedate,''))) >= 4
        AND CAST(LEFT(TRIM(releasedate), 4) AS UNSIGNED) <= #{yearMax}




        ORDER BY rating DESC, comicid DESC


        ORDER BY updated_at DESC, comicid DESC


        ORDER BY comicid DESC


LIMIT #{offset}, 20

SELECT * FROM 0721acgn.tb_cartoons WHERE TRIM(IFNULL(name, '')) = TRIM(#{name})
AND comicid != #{excludeId}
ORDER BY comicid DESC LIMIT 30

SELECT * FROM 0721acgn.tb_cartoons WHERE CHAR_LENGTH(#{seriesPrefix}) >= 3
AND comicid != #{excludeId}
AND TRIM(IFNULL(name, '')) LIKE CONCAT(#{seriesPrefixEsc}, '%') ESCAPE '!' ORDER BY comicid DESC LIMIT 200
